// This file is generated by AI.

// 参考音频列表编辑器 (搜索 + 列表 + 添加), 「编辑角色」与「选择参考音频」共用。
//
// 为什么是一个共享组件: 这两处**本来就是同一件事** —— 看一个角色的参考音频, 挑一条,
// 或者补一条。以前这里有两套实现 (选择器里内联了一套"选文件 + 在底部填参考文本"的
// 添加流程, 编辑角色里用的是 `AddReferenceDialog`), 于是同一个动作在两个地方长得不一样:
// 一个有搜索框一个没有, 一个加完就退出一个留在原地, 添加按钮的样式与位置也不同。
// 共享之后它们在结构上不可能再分叉。
//
// 交互约定:
// * **就在原地加**: 「添加参考音频」打开的是同一个 `AddReferenceDialog`, 加完列表就地
//   刷新, 父对话框不会退出 —— 补齐一个角色的语料往往要连着加好几条;
// * 选择器场景 (`onPick` 存在) 里点条目即选中, 并把选中态交给调用方;
// * 没有参考音频选择之外的批量操作: 导出角色属于「编辑角色」/「选择角色」的职责,
//   不在这里出现。

import { Button, Input } from '@fluentui/react-components';
import { AddRegular, DeleteRegular } from '@fluentui/react-icons';
import { useEffect, useMemo, useState } from 'react';

import type { Character, ReferenceAudio } from '../commands/voice';
import { voiceRemoveReference } from '../commands/voice';
import { useAppStore } from '../state/store';
import { AddReferenceDialog } from './AddReferenceDialog';
import { AudioButton } from './AudioButton';
import { voiceController } from './controller';
import { LANGUAGE_LABELS } from './types';

interface Props {
  character: Character;
  /** 选择器场景: 当前选中的参考音频 (高亮显示) */
  selectedHash?: string | null;
  /** 选择器场景: 点条目即选中。不传表示只做编辑 (编辑角色对话框) */
  onPick?: (hash: string) => void;
  /**
   * 选择器场景: 刚添加了一条。
   *
   * 与 `onPick` 分开是必要的 —— 点条目意味着"选好了" (可以关掉对话框),
   * 而"又加了一条"往往只是批量补语料的第一步, 对话框要留在原地。合成一个回调就只能
   * 二选一, 而之前的表现正是"加完就把参考音频选择框一起关掉"。
   */
  onAdded?: (hash: string) => void;
  /** 列表内容已变化 (增删), 调用方据此刷新自己持有的角色快照 */
  onChanged: () => void;
}

export function ReferenceListEditor({ character, selectedHash = null, onPick, onAdded, onChanged }: Props) {
  const [query, setQuery] = useState('');
  const [addOpen, setAddOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // 换角色时清空搜索与报错 (它们都属于"上一个角色"的上下文)
  useEffect(() => {
    setQuery('');
    setError(null);
  }, [character.id]);

  const references = useMemo(() => {
    const list = character.references;
    const needle = query.trim().toLowerCase();
    if (!needle) return list;
    return list.filter(
      (reference) =>
        reference.text.toLowerCase().includes(needle) ||
        reference.tags.some((tag) => tag.toLowerCase().includes(needle))
    );
  }, [character.references, query]);

  const removeReference = async (reference: ReferenceAudio) => {
    setBusy(true);
    setError(null);
    try {
      const updated = await voiceRemoveReference(character.id, reference.hash);
      voiceController.setCharacters(
        useAppStore.getState().voiceCharacters.map((item) => (item.id === updated.id ? updated : item))
      );
      onChanged();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  const total = character.references.length;

  return (
    <div className="reference-editor">
      <div className="dialog-toolbar">
        <Input
          className="dialog-toolbar-grow"
          placeholder="搜索参考文本或标签…"
          value={query}
          onChange={(_, data) => setQuery(data.value)}
        />
        {/* 计数放在搜索框与按钮之间: 搜索时显示"匹配 N / 共 M", 平时只显示总数 */}
        <span className="reference-count">
          {query.trim() ? `匹配 ${references.length} / 共 ${total}` : `共 ${total} 条`}
        </span>
        <Button appearance="primary" icon={<AddRegular />} disabled={busy} onClick={() => setAddOpen(true)}>
          添加参考音频
        </Button>
      </div>

      <div className="reference-list dialog-scroll">
        {total === 0 && (
          <p className="voice-dialog-empty">还没有参考音频。参考文本必须与音频逐字一致, 时长 3~10 秒。</p>
        )}
        {total > 0 && references.length === 0 && <p className="voice-dialog-empty">没有匹配的参考音频。</p>}
        {references.map((reference) => (
          <div key={reference.hash} className={`reference-item${reference.hash === selectedHash ? ' selected' : ''}`}>
            {/*
              条目主体: 选择器场景里是按钮 (点一下就用这条), 编辑角色里只是说明文字。
              两种场景渲染成不同元素, 而不是同一个按钮加 disabled —— 后者会带上一套
              "不可用"的灰化样式, 看起来像出了故障。
            */}
            <ReferenceBody reference={reference} onPick={onPick ? () => onPick(reference.hash) : undefined} />
            <AudioButton path={voiceController.referencePathFor(character.id, reference.file)} />
            <Button
              size="small"
              appearance="subtle"
              className="danger-icon"
              icon={<DeleteRegular />}
              title="删除该参考音频"
              disabled={busy}
              onClick={() => void removeReference(reference)}
            />
          </div>
        ))}
      </div>

      {error && <p className="voice-error">{error}</p>}

      {addOpen && (
        <AddReferenceDialog
          character={character}
          onClose={() => setAddOpen(false)}
          onAdded={(added) => {
            // 加完留在原地 (只关掉添加对话框): 刷新列表, 选择器场景把新条目设为当前项
            onChanged();
            onAdded?.(added.hash);
          }}
        />
      )}
    </div>
  );
}

/** 条目的文本与元信息 (选择器场景下可点选) */
function ReferenceBody({ reference, onPick }: { reference: ReferenceAudio; onPick?: () => void }) {
  const content = (
    <>
      <span className="reference-text">{reference.text || '（未填写参考文本）'}</span>
      <span className="reference-meta">
        {LANGUAGE_LABELS[reference.language] ?? reference.language} · {reference.duration.toFixed(2)}s ·{' '}
        {Math.round(reference.sampleRate / 1000)}kHz
        {reference.tags.length > 0 && ` · ${reference.tags.join(' / ')}`}
      </span>
    </>
  );

  if (!onPick) return <div className="reference-main reference-main-static">{content}</div>;
  return (
    <button type="button" className="reference-main" title="使用这条参考音频" onClick={onPick}>
      {content}
    </button>
  );
}
